def mp_preview(slug,mini):
    tags='<div class="tag"><i></i>[выгода 1]</div><div class="tag"><i></i>[выгода 2]</div>'+('' if mini else '<div class="tag"><i></i>[выгода 3]</div>')
    return f'<div class="pv pv-{slug}{" mini" if mini else ""}"><div class="mp"><span class="sale">[−XX%]</span><h3>УТП товара до 5 слов</h3>{tags}<div class="prod"></div></div></div>'
